// Function to check if a word matches the target word
bool isTargetWord(const std::string& word, const std::string& target) {
    // Ignore case by converting both to lowercase
    std::string lowerWord = word;
    std::string lowerTarget = target;
    std::transform(lowerWord.begin(), lowerWord.end(), lowerWord.begin(), ::tolower);
    std::transform(lowerTarget.begin(), lowerTarget.end(), lowerTarget.begin(), ::tolower);
    return lowerWord == lowerTarget;
}

// Function to split a line into words
std::vector<std::string> splitIntoWords(const std::string& line) {
    std::vector<std::string> words;
    std::istringstream iss(line);
    std::string word;
    while (iss >> word) {
        // Remove punctuation from the word
        word.erase(std::remove_if(word.begin(), word.end(), ::ispunct), word.end());
        words.push_back(word);
    }
    return words;
}

